revision.text:
/* Template:Card/styles.css: cards with a button along the bottom (TemplateStyles).
   Put cards inside <div class="rp-cards"> to lay them out side by side. */
.rp-cards {
	display: grid;
	grid-template-columns: repeat( auto-fit, minmax( 240px, 1fr ) );
	gap: 12px;
	margin: 1em 0 1.6em;
}
.rp-cards--2 {
	grid-template-columns: repeat( auto-fit, minmax( 300px, 1fr ) );
}
.rp-card {
	display: flex;
	flex-direction: column;
	justify-content: space-between;
	min-width: 0;
	overflow: hidden;
	border: 1px solid rgba( 127, 127, 127, 0.28 );
	border-radius: 12px;
	background: rgba( 127, 127, 127, 0.07 );
	font-size: 0.875rem;
	line-height: 1.55;
	transition: border-color 0.15s, transform 0.15s;
}
.rp-card:hover {
	border-color: rgba( 127, 127, 127, 0.55 );
	transform: translateY( -2px );
}
.rp-card-body {
	padding: 16px 18px;
}
.rp-card-body p:first-child {
	margin-top: 0;
}
.rp-card-body p:last-child {
	margin-bottom: 0;
}
.rp-card-title {
	margin-bottom: 8px;
	font-size: 1.125rem;
	font-weight: 600;
	line-height: 1.25;
}
.rp-card-button a,
.rp-card-button a:visited,
.rp-card-button a.new {
	display: block;
	padding: 10px;
	color: #fff;
	font-weight: 600;
	text-align: center;
	text-decoration: none;
}
.rp-card-button:hover {
	filter: brightness( 1.12 );
}
.rp-card-button--blue { background: #3366cc; }
.rp-card-button--green { background: #2e7d32; }
.rp-card-button--orange { background: #ef6c00; }
.rp-card-button--purple { background: #7e57c2; }
.rp-card-button--red { background: #c62828; }
.rp-card-button--soon { background: rgba( 127, 127, 127, 0.35 ); }

/* "Start a new page" boxes */
.rp-create {
	margin: 1em 0 1.6em;
	padding: 16px 18px;
	border: 1px solid rgba( 127, 127, 127, 0.28 );
	border-radius: 12px;
	background: rgba( 127, 127, 127, 0.07 );
}
.rp-create .mw-inputbox-centered {
	margin: 0.5em 0;
}
.rp-create form {
	display: flex;
	flex-wrap: wrap;
	justify-content: flex-start !important;
	gap: 8px;
	text-align: left;
}
.rp-create .cdx-text-input {
	flex: 0 1 280px;
	min-width: 0;
}
.rp-create .cdx-text-input input {
	width: 100%;
}

.rp-note {
	margin: 1em 0;
	padding: 10px 15px;
	border-radius: 8px;
	background: rgba( 127, 127, 127, 0.1 );
	font-size: 0.875rem;
	opacity: 0.9;
}
